insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g6_ela_v1'
from (values
('110.22.b.2.A',2,'Which part of a dictionary entry shows how to say a word aloud?','["the pronunciation respelling", "the part-of-speech label only", "the etymology only", "the sample sentence only"]'::jsonb,0,'Respellings in parentheses guide pronunciation.','original'),
('110.22.b.2.A',3,'A dictionary entry lists ''rec-og-nize'' with a dot or dash between the chunks. What does this show?','["how the word is spelled in Latin", "how the word is divided into syllables", "where the word was first used", "what the word rhymes with"]'::jsonb,1,'Syllable breaks help with decoding and line breaks.','original'),
('110.22.b.2.A',3,'A student wants to know which language a word came from. Which dictionary feature should be checked?','["the example sentence", "the guide words", "the word origin note", "the pronunciation key"]'::jsonb,2,'Etymology notes give word origins.','original'),
('110.22.b.2.A',4,'A dictionary lists ''permit'' as both a verb and a noun, with the stress on a different syllable in each. What should a reader do to choose the correct pronunciation?','["always use the first entry", "ignore the stress marks", "choose the shortest entry", "use the part of speech from the sentence to pick the matching entry"]'::jsonb,3,'Stress and meaning change with part of speech.','original'),
('110.22.b.2.B',2,'''The arid desert received almost no rain, so its dry soil cracked.'' What does ''arid'' mean?','["very dry", "very large", "full of animals", "very cold"]'::jsonb,0,'The sentence gives ''dry soil'' and ''no rain'' as clues.','original'),
('110.22.b.2.B',3,'''Maya was reluctant to jump, hesitating at the edge of the pool for several minutes.'' What does ''reluctant'' mean?','["angry", "unwilling", "tired", "eager"]'::jsonb,1,'Hesitating shows she did not want to jump.','original'),
('110.22.b.2.B',3,'''The scientist''s hypothesis, or educated guess, was tested in three trials.'' What is the ''hypothesis''?','["a final result", "a trial", "an educated guess", "a tool"]'::jsonb,2,'The phrase set off by commas defines the word.','original'),
('110.22.b.2.B',4,'''Unlike her gregarious brother, who loved parties, Tia preferred to stay home alone.'' What does ''gregarious'' most likely mean?','["shy", "wealthy", "clumsy", "sociable"]'::jsonb,3,'The word ''unlike'' signals an opposite of staying home alone.','original'),
('110.22.b.2.C',2,'The Latin root ''port'' means ''carry.'' Which word means ''able to be carried''?','["portable", "portion", "porch", "portal"]'::jsonb,0,'Port + able = can be carried.','original'),
('110.22.b.2.C',3,'The Greek root ''tele'' means ''far.'' What does ''telescope'' most likely mean?','["a map of stars", "an instrument for viewing far-off things", "a close-up lens", "a type of clock"]'::jsonb,1,'Tele (far) + scope (view).','original'),
('110.22.b.2.C',3,'The Latin root ''dict'' means ''say.'' Which word fits ''a formal statement ordered by a ruler''?','["contradict", "predict", "edict", "dictionary"]'::jsonb,2,'An edict is something said or declared with authority.','original'),
('110.22.b.2.C',4,'The root ''bio'' means ''life'' and ''graph'' means ''write.'' What is a ''biography''?','["a drawing of an animal", "a list of rules", "a study of rocks", "a written account of a person''s life"]'::jsonb,3,'Bio (life) + graph (write).','original'),
('110.22.b.5.B',3,'A student reads the first paragraph of an article about volcanoes. Which question would best deepen understanding before reading on?','["What causes a volcano to erupt?", "How many pages are there?", "Who published the magazine?", "What color is the cover?"]'::jsonb,0,'A question about the topic guides reading.','original'),
('110.22.b.5.B',4,'Which question would a reader ask AFTER reading to check the main idea of a text about coral reefs?','["Is the font easy to read?", "What was the most important point about coral reefs?", "Where was the book printed?", "What is the page count?"]'::jsonb,1,'After-reading questions examine key ideas.','original'),
('110.22.b.5.B',3,'Asking ''Why did the character make that choice?'' while reading is a way to...','["skip hard parts", "avoid the plot", "dig deeper into the text", "memorize the author''s name"]'::jsonb,2,'Questions deepen understanding.','original'),
('110.22.b.5.C',3,'A text has the headings ''Causes,'' ''Effects,'' and ''Solutions.'' What can a reader predict about its structure?','["it is a play script", "it is a poem", "it is a diary", "it explains a problem and how to respond to it"]'::jsonb,3,'Headings reveal organization.','original'),
('110.22.b.5.C',3,'A story begins ''Once upon a time, in a kingdom beyond the hills...'' What genre is most likely?','["fairy tale", "biography", "news report", "science article"]'::jsonb,0,'The opening is a fairy-tale convention.','original'),
('110.22.b.5.C',4,'A reader predicted that a character would apologize, but the character stormed away. What should the reader do?','["stop reading", "correct the prediction using the new evidence", "change the title", "ignore the new text"]'::jsonb,1,'Good readers confirm or correct predictions.','original'),
('110.22.b.5.D',2,'Which sentence would help a reader create the clearest mental image?','["Something happened in the sky.", "It was nice outside.", "The red kite dipped and swirled above the snowy field.", "The kite was there."]'::jsonb,2,'Concrete details help readers visualize.','original'),
('110.22.b.5.D',3,'A reader pictures a dark, creaking cabin after reading ''The floorboards groaned under each step.'' Which technique is this?','["paraphrasing", "skimming", "citing", "visualizing"]'::jsonb,3,'Creating images from details deepens understanding.','original'),
('110.22.b.5.D',3,'Which detail best supports picturing a stormy sea?','["waves hammered the deck while thunder cracked overhead", "the sailors had lunch", "a flag hung on the mast", "the boat was painted white"]'::jsonb,0,'Active, sensory details show the storm.','original'),
('110.22.b.5.E',2,'A student reads about a character who moves to a new school and recalls her own first day. This is a connection to...','["another text", "personal experience", "an author''s biography", "society"]'::jsonb,1,'Text-to-self connection.','original'),
('110.22.b.5.E',3,'After reading about a fire in a novel, a student thinks about an article on fire safety. This is a connection to...','["a dictionary", "personal experience", "another text", "a map"]'::jsonb,2,'Text-to-text connection.','original'),
('110.22.b.5.E',4,'A reader connects a story about unfair rules to a current debate about school policies. This is a connection to...','["only the setting", "only the plot", "only the author", "society"]'::jsonb,3,'Text-to-world connection.','original'),
('110.22.b.5.F',3,'''Jada stared at the empty chair, then slowly folded the note and slipped it into her pocket.'' What can be inferred?','["Jada is sad or upset about someone''s absence", "Jada is eager to start a game", "Jada is going to sleep", "Jada is angry about dinner"]'::jsonb,0,'Her slow, quiet actions imply sadness.','original'),
('110.22.b.5.F',3,'''Carlos grabbed his umbrella and pulled on his boots before leaving.'' What can be inferred about the weather?','["it is calm and sunny", "it is raining or about to rain", "it is snowing heavily", "it is a heat wave"]'::jsonb,1,'Umbrella and boots suggest rain.','original'),
('110.22.b.5.F',4,'''The dog thumped its tail and pulled the leash toward the door.'' Which inference is best supported?','["the dog is afraid", "the dog is asleep", "the dog wants to go outside", "the dog is angry"]'::jsonb,2,'Tail thumping and pulling show eagerness.','original'),
('110.22.b.5.G',3,'Which detail is MOST important to the key idea of an article about recycling''s benefits?','["the article has a blue border", "a photo shows a truck", "the author lives in Ohio", "recycling reduces waste in landfills"]'::jsonb,3,'Key ideas are central to the message.','original'),
('110.22.b.5.G',4,'A passage describes three ways bees help crops and one way bees make honey. The key idea is most likely...','["bees are important to farming", "crops need no care", "honey is expensive", "bees are hard to find"]'::jsonb,0,'Most details support pollination''s importance.','original'),
('110.22.b.5.G',3,'To find the key idea in a paragraph, a reader should...','["check the last letter", "decide what the details have in common", "look at the page number", "count the words"]'::jsonb,1,'Details point to the main message.','original'),
('110.22.b.5.H',3,'A student reads two articles about ocean pollution and combines facts from both to explain solutions. This is...','["guessing", "copying", "synthesizing", "skimming"]'::jsonb,2,'Combining sources creates new understanding.','original'),
('110.22.b.5.H',4,'Article A says plastic harms sea turtles. Article B says plastic breaks into tiny pieces that enter the food chain. Which synthesis is best?','["the articles disagree about turtles", "plastic is a type of toy", "sea turtles never eat", "plastic harms ocean animals directly and spreads through the food chain"]'::jsonb,3,'Merges both ideas.','original'),
('110.22.b.5.H',4,'Which statement shows synthesis rather than summary of one text?','["Combining the interview and the report shows the policy affects both students and teachers.", "The report is eight pages long.", "The interview starts on page two.", "The report has a title."]'::jsonb,0,'Synthesis builds a new idea from several sources.','original'),
('110.22.b.5.I',2,'A reader no longer understands a paragraph. What is a good fix-up strategy?','["close the book forever", "re-read it", "skip the whole chapter", "guess the ending"]'::jsonb,1,'Re-reading clarifies meaning.','original'),
('110.22.b.5.I',3,'Which strategy helps a reader who meets an unknown word?','["memorize the page", "change the font", "use context clues or look it up", "skip every sentence with it"]'::jsonb,2,'Fix-up strategies address confusion.','original'),
('110.22.b.5.I',4,'A reader keeps losing track of characters. Which adjustment is most useful?','["read faster", "read only the last page", "ignore the names", "make a quick list of characters and their roles"]'::jsonb,3,'Notetaking aids comprehension.','original'),
('110.22.b.6.C',3,'Claim: ''The narrator is nervous.'' Which evidence best supports the claim?','["The narrator''s hands shook as she approached the stage.", "The show started at seven.", "The audience clapped politely.", "The stage was painted green."]'::jsonb,0,'Direct detail shows nervousness.','original'),
('110.22.b.6.C',3,'Which is the strongest piece of text evidence for ''The town is poor''?','["It rained on Tuesday.", "Many houses had boarded windows and bare cupboards.", "The mayor wore a hat.", "The town has a river."]'::jsonb,1,'Concrete details show poverty.','original'),
('110.22.b.6.C',4,'A student writes ''The author thinks school lunches should be healthier'' but gives no support. What is missing?','["a bigger font", "a longer title", "a quotation or detail from the text", "a drawing"]'::jsonb,2,'Responses need textual evidence.','original'),
('110.22.b.6.D',2,'A good summary of a text should include...','["only your opinion", "the first sentence word for word", "every detail", "the main ideas in your own words"]'::jsonb,3,'Summaries are short and keep meaning.','original'),
('110.22.b.6.D',3,'Which is the best paraphrase of ''The sun dipped below the horizon, painting the sky orange''?','["The sun set and the sky turned orange.", "The horizon vanished.", "The sky was empty.", "The sun rose in the east."]'::jsonb,0,'Paraphrase keeps the meaning in new words.','original'),
('110.22.b.6.D',4,'Which sentence is a summary rather than a paraphrase of one line?','["The river rose by two feet.", "The article explains how floods form and how towns prepare.", "Floods form when rivers rise.", "Towns must pay for sandbags."]'::jsonb,1,'A summary covers the whole text.','original'),
('110.22.b.6.G',3,'''Dad said he would be home by six. At nine, Elena was still setting the table for two.'' What is the implicit meaning?','["Dad is cooking", "Dad arrived early", "Elena is still waiting and hoping he will come", "Elena dislikes dinner"]'::jsonb,2,'The meaning is implied, not stated.','original'),
('110.22.b.6.G',3,'An explicit meaning in a text is one that is...','["hidden in the title only", "shown only in pictures", "never written", "directly stated"]'::jsonb,3,'Explicit means clearly stated.','original'),
('110.22.b.6.G',4,'''The old swing swayed gently in the empty yard.'' Which implicit idea is most likely suggested?','["loneliness or something missing", "a sports game", "a loud celebration", "a busy playground"]'::jsonb,0,'Empty settings suggest absence.','original'),
('110.22.b.7.A',3,'In a story, a boy refuses help, struggles, then accepts it and succeeds. Which theme is best supported?','["lying is useful", "accepting help can lead to success", "wealth brings happiness", "it is wrong to try"]'::jsonb,1,'The plot shows the lesson.','original'),
('110.22.b.7.A',4,'A theme is best described as...','["the place where the story happens", "the order of events", "a message about life or human nature in a text", "the author''s birthplace"]'::jsonb,2,'Themes are underlying messages.','original'),
('110.22.b.7.A',4,'Two stories show characters who lose a contest but learn teamwork. What theme runs across both?','["teams never work", "winning is everything", "contests are unfair", "cooperation matters more than winning"]'::jsonb,3,'The shared lesson is the theme.','original'),
('110.22.b.7.B',3,'A character is embarrassed when she forgets her lines, so she quits the play. Which type of response is quitting?','["an external response", "a theme", "a setting", "an internal response"]'::jsonb,0,'Actions are external; feelings are internal.','original'),
('110.22.b.7.B',3,'Which is an INTERNAL response?','["They waved goodbye.", "He felt a wave of jealousy.", "She ran down the hall.", "He slammed the door."]'::jsonb,1,'Thoughts and feelings are internal.','original'),
('110.22.b.7.B',4,'How does a character''s fear of failure most likely develop the plot when she hides her test?','["it changes the setting", "it ends the story at once", "it creates a problem she must face later", "it removes all conflict"]'::jsonb,2,'Choices create conflict.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g6_ela_v1'
from (values
('110.22.b.7.C',2,'The part of a plot where the problem reaches its highest tension is the...','["resolution", "exposition", "title", "climax"]'::jsonb,3,'The climax is the turning point.','original'),
('110.22.b.7.C',3,'A story opens with the ending, then goes back in time to show how events led there. This is a...','["non-linear plot (flashback)", "rhyme scheme", "linear plot", "stanza"]'::jsonb,0,'Order of events is rearranged.','original'),
('110.22.b.7.C',4,'After the main conflict is settled, the events that follow and tie up loose ends are called...','["foreshadowing", "falling action and resolution", "rising action", "exposition"]'::jsonb,1,'These follow the climax.','original'),
('110.22.b.7.D',3,'A story is set during a harsh winter in 1850s Texas. How might the setting influence the plot?','["the characters will be on a beach", "the setting has no effect", "scarce supplies could force characters to make hard choices", "it ensures the story is funny"]'::jsonb,2,'Setting creates challenges.','original'),
('110.22.b.7.D',3,'A character raised in a fishing village knows how to read tides. This detail shows how...','["the title was chosen", "the climax occurs", "the author''s age matters", "culture and setting shape the character"]'::jsonb,3,'Cultural setting shapes skills.','original'),
('110.22.b.7.D',4,'Why does historical setting matter in a story about a girl denied the vote?','["it explains the rules and attitudes that cause her conflict", "it changes the font", "it hides the theme", "it replaces the plot"]'::jsonb,0,'Historical context drives conflict.','original'),
('110.22.b.8.A',2,'A story in which detectives follow clues to solve a crime belongs to which genre?','["biography", "mystery", "poetry", "encyclopedia entry"]'::jsonb,1,'Mysteries focus on clues and solving crimes.','original'),
('110.22.b.8.A',3,'A story set in the past that uses real events and invented characters is...','["autobiography", "science article", "historical fiction", "fable only"]'::jsonb,2,'It blends real history with fiction.','original'),
('110.22.b.8.A',3,'A story with a tense journey, danger and daring escapes is most likely a(n)...','["recipe", "textbook", "news article", "adventure story"]'::jsonb,3,'Adventure stories feature risk and action.','original'),
('110.22.b.8.B',3,'A poet breaks a line in the middle of a sentence to make readers pause. This effect comes from...','["a line break", "an index", "a title", "a footnote"]'::jsonb,0,'Line breaks control pacing.','original'),
('110.22.b.8.B',3,'A poem with a regular pattern of stressed and unstressed syllables has a steady...','["glossary", "meter", "setting", "plot"]'::jsonb,1,'Meter is the rhythm of a poem.','original'),
('110.22.b.8.B',4,'A poem has no rhyme or regular meter. It is called...','["a haiku", "a sonnet", "free verse", "a limerick"]'::jsonb,2,'Free verse lacks fixed patterns.','original'),
('110.22.b.8.C',3,'In a play, a character''s personality is mostly revealed through...','["glossaries", "footnotes", "indexes", "dialogue and actions"]'::jsonb,3,'Plays rely on speech and staging.','original'),
('110.22.b.8.C',3,'Stage directions in a script are used to tell...','["actors and directors how to move, speak, or what the set looks like", "readers the definition of words", "when the play will end", "the author''s address"]'::jsonb,0,'They guide staging.','original'),
('110.22.b.8.C',4,'A playwright has a character whisper to a rival while another character looks away. What is the playwright showing?','["a footnote", "tension through staging and speech", "the climax''s resolution", "a flashback"]'::jsonb,1,'Staging and dialogue show relationships.','original'),
('110.22.b.8.F',3,'A webpage includes text, a video and a clickable map. This is an example of a...','["letter", "myth", "multimodal text", "limerick"]'::jsonb,2,'It uses more than one mode.','original'),
('110.22.b.8.F',3,'Which feature is unique to digital texts?','["titles", "paragraph indents", "page numbers", "hyperlinks that lead to more information"]'::jsonb,3,'Links connect to other content.','original'),
('110.22.b.8.F',4,'A reader evaluates a website''s infographic. Which question is most useful?','["Does the image clearly show the data being described?", "How many pixels is it?", "Who made the font?", "Is the background blue?"]'::jsonb,0,'Evaluation looks at effectiveness.','original'),
('110.22.b.8.D.i',3,'The controlling idea of an informational essay is its...','["last sentence only", "central idea or thesis", "title page", "glossary"]'::jsonb,1,'It ties details together.','original'),
('110.22.b.8.D.i',4,'An essay says ''Cities should plant more trees.'' Which detail best supports it?','["Some trees lose leaves.", "Trees are tall.", "Trees lower summer temperatures and clean the air.", "Cities have buildings."]'::jsonb,2,'Evidence supports the thesis.','original'),
('110.22.b.8.D.i',3,'Which sentence states a controlling idea?','["The gym opens at six.", "The author is a coach.", "Exercise is on page three.", "Regular exercise improves both health and mood."]'::jsonb,3,'It makes a claim covering the details.','original'),
('110.22.b.8.D.ii',3,'Which text feature lists the sources the author used?','["references", "the headline", "the foreword", "the preface"]'::jsonb,0,'References credit sources.','original'),
('110.22.b.8.D.ii',3,'A short note at the start of a book explaining why the author wrote it is a...','["bibliography", "preface", "index", "glossary"]'::jsonb,1,'Prefaces give background.','original'),
('110.22.b.8.D.ii',4,'A reader wants to know who the author thanks for help. Where should the reader look?','["the index", "the glossary", "the acknowledgements", "the table of contents"]'::jsonb,2,'Acknowledgements thank contributors.','original'),
('110.22.b.8.D.iii',3,'A passage describes the benefits and drawbacks of electric cars. Which pattern is used?','["chronological order", "poetry", "cause and effect only", "advantage and disadvantage"]'::jsonb,3,'It weighs pros and cons.','original'),
('110.22.b.8.D.iii',3,'A text sorts animals into groups such as mammals, birds, and reptiles. The pattern is...','["classification", "problem and solution", "definition only", "sequence"]'::jsonb,0,'It organizes into categories.','original'),
('110.22.b.8.D.iii',4,'A paragraph begins with the word ''Photosynthesis is the process by which...'' and then explains it. The pattern is...','["chronology", "definition", "compare and contrast", "persuasion"]'::jsonb,1,'It defines a term.','original'),
('110.22.b.8.E.i',3,'In an argumentative text, the claim is...','["the author''s name", "the title font", "the writer''s position on an issue", "a list of sources"]'::jsonb,2,'The claim states the argument.','original'),
('110.22.b.8.E.i',3,'Which sentence is a claim?','["Schools open at eight.", "Students carry backpacks.", "Buses are yellow.", "Schools should start later in the morning."]'::jsonb,3,'It takes a position.','original'),
('110.22.b.8.E.i',4,'A writer argues ''Our town needs a skate park.'' What is the claim?','["the town needs a skate park", "parks cost money", "skate parks are on streets", "teens skate"]'::jsonb,0,'The claim is the stated position.','original'),
('110.22.b.8.E.ii',3,'Which is an example of statistical evidence?','["Everyone knows later is better.", "Seventy percent of students surveyed prefer later start times.", "It feels right.", "I think it is better."]'::jsonb,1,'Statistics offer numeric evidence.','original'),
('110.22.b.8.E.ii',4,'An author quotes a doctor to support a claim about sleep. This evidence is...','["a simile", "a rhyme", "an expert testimony", "a personal anecdote only"]'::jsonb,2,'Experts add credibility.','original'),
('110.22.b.8.E.ii',3,'A writer shares a short story about a single student to support a claim. This evidence is a(n)...','["glossary", "statistic", "definition", "anecdote"]'::jsonb,3,'Anecdotes use personal examples.','original'),
('110.22.b.8.E.iii',3,'A flyer says ''Join the middle school science club! No experience needed!'' Who is the intended audience?','["middle school students", "retired teachers", "adult scientists", "toddlers"]'::jsonb,0,'The wording targets students.','original'),
('110.22.b.8.E.iii',4,'An article about retirement savings uses terms like ''portfolio'' and ''annuity.'' The intended audience is probably...','["movie fans", "adults planning for retirement", "pet owners", "kindergartners"]'::jsonb,1,'Vocabulary shows the reader.','original'),
('110.22.b.8.E.iii',3,'A letter to the school board about bus routes is aimed at...','["students at recess", "sports fans", "school board members", "bakery customers"]'::jsonb,2,'The addressee is the audience.','original'),
('110.22.b.9.A',2,'A text that teaches readers how volcanoes form has which main purpose?','["to entertain only", "to confuse", "to persuade only", "to inform"]'::jsonb,3,'Informational texts explain.','original'),
('110.22.b.9.A',3,'An article urges readers to adopt shelter dogs. The author''s purpose is to...','["persuade", "describe a setting", "inform with neutral facts", "entertain with a joke"]'::jsonb,0,'It calls for action.','original'),
('110.22.b.9.A',4,'A fable about a tortoise and a hare ends with a moral. What is the author''s message?','["races are illegal", "slow and steady effort can beat careless speed", "tortoises are fast", "hares are slow"]'::jsonb,1,'The moral is the message.','original'),
('110.22.b.9.B',3,'An author explains a problem and then describes how it was fixed. This structure helps the author...','["describe a rhyme", "tell a joke", "show a problem and solution", "avoid details"]'::jsonb,2,'Structure supports purpose.','original'),
('110.22.b.9.B',4,'A history article is arranged in order of dates. How does this structure support the author''s purpose?','["it hides the causes", "it makes the text a poem", "it removes all facts", "it helps readers follow events as they happened"]'::jsonb,3,'Chronology clarifies sequence.','original'),
('110.22.b.9.B',3,'A compare-and-contrast structure helps an author...','["show similarities and differences", "tell a story", "describe a place", "list steps"]'::jsonb,0,'That is the structure''s function.','original'),
('110.22.b.9.C',3,'Why might an author use bold type for key terms?','["to change the genre", "to help readers notice important vocabulary", "to make the text longer", "to hide the details"]'::jsonb,1,'Bold signals importance.','original'),
('110.22.b.9.C',3,'A diagram labeled ''Parts of a Cell'' is included in a science article. Its purpose is to...','["tell a story", "entertain with a rhyme", "show information visually", "give the author''s name"]'::jsonb,2,'Graphics clarify content.','original'),
('110.22.b.9.C',4,'Why would an author include a map in a text about an expedition?','["to hide the date", "to rhyme with the text", "to replace the title", "to help readers see the route and places"]'::jsonb,3,'Maps show location and routes.','original'),
('110.22.b.9.D',2,'''The wind whispered through the trees'' is an example of...','["personification", "alliteration", "idiom", "metaphor"]'::jsonb,0,'The wind is given a human action.','original'),
('110.22.b.9.D',3,'''Time is a thief'' is a...','["hyperbole", "metaphor", "simile", "personification"]'::jsonb,1,'It compares without ''like'' or ''as.''','original'),
('110.22.b.9.D',4,'''The classroom was a zoo'' helps the author...','["describe real animals", "state the date", "show the room was loud and chaotic", "list school rules"]'::jsonb,2,'The metaphor conveys noise and disorder.','original'),
('110.22.b.9.E',3,'A narrator who knows the thoughts of every character uses which point of view?','["first person", "second person", "limited", "omniscient"]'::jsonb,3,'Omniscient narrators know everything.','original'),
('110.22.b.9.E',3,'A narrator tells only what one character thinks and sees, using ''he'' or ''she.'' This is...','["third-person limited", "first-person plural", "second-person", "omniscient"]'::jsonb,0,'It limits knowledge to one character.','original'),
('110.22.b.9.E',4,'Why would an author use a limited point of view in a mystery?','["to add footnotes", "to keep readers from knowing everything the detective doesn''t", "to reveal all secrets at once", "to remove suspense"]'::jsonb,1,'Limited view builds suspense.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g6_ela_v1'
from (values
('110.22.b.9.F',3,'''The silent halls were dim and cold'' creates which mood?','["cheerful", "silly", "eerie or gloomy", "excited"]'::jsonb,2,'Word choice sets mood.','original'),
('110.22.b.9.F',3,'An author''s distinctive way of expressing ideas, shown through word choice and sentence style, is called...','["setting", "plot", "theme", "voice"]'::jsonb,3,'Voice is the author''s personality in writing.','original'),
('110.22.b.9.F',4,'Which phrase would most likely create a joyful mood?','["sunlight spilled over the laughing crowd", "a chill crept along the wall", "gloom settled over the ruins", "the shadows closed in"]'::jsonb,0,'Positive imagery sets a joyful mood.','original'),
('110.22.b.9.G',3,'Which is a logical fallacy?','["A doctor recommends daily exercise.", "Everyone is buying it, so it must be the best.", "The data shows a 5% rise.", "Studies show regular sleep improves focus."]'::jsonb,1,'Bandwagon appeal is a fallacy.','original'),
('110.22.b.9.G',4,'Repeating a key phrase for emphasis in a speech is a(n)...','["glossary entry", "plot twist", "rhetorical device", "logical fallacy"]'::jsonb,2,'Repetition persuades through style.','original'),
('110.22.b.9.G',4,'''Either we ban all cars or the planet is doomed'' is a fallacy because it...','["uses a metaphor", "cites an expert", "includes data", "offers only two extreme choices"]'::jsonb,3,'That is a false dilemma.','original'),
('110.22.b.10.B.i',3,'Which word helps connect two paragraphs by showing contrast?','["however", "first", "therefore", "similarly"]'::jsonb,0,'However signals a contrast.','original'),
('110.22.b.10.B.i',3,'An introduction in an essay should...','["list every detail", "present the topic and the controlling idea", "repeat the conclusion", "avoid the topic"]'::jsonb,1,'Introductions orient readers.','original'),
('110.22.b.10.B.i',4,'Which sentence best works as a transition between a paragraph on benefits and one on drawbacks?','["Pizza is popular.", "The end.", "Despite these advantages, there are some concerns.", "In conclusion, I like dogs."]'::jsonb,2,'It links the two ideas.','original'),
('110.22.b.10.C',3,'Which revision adds sentence variety to ''I ran. I jumped. I fell.''?','["I ran I jumped I fell.", "Ran jumped fell.", "I ran. I ran. I ran.", "I ran, jumped, and then tumbled to the ground."]'::jsonb,3,'Combining sentences adds variety.','original'),
('110.22.b.10.C',3,'Which word choice is more precise than ''nice''?','["generous", "okay", "fine", "good"]'::jsonb,0,'Precise words clarify meaning.','original'),
('110.22.b.10.C',4,'A paragraph about pets suddenly mentions a baseball game. In revision, the writer should...','["delete the topic sentence", "remove the unrelated sentence", "change all verbs", "add more baseball"]'::jsonb,1,'Revision maintains focus.','original'),
('110.22.b.10.D.i',3,'Which sentence is a run-on?','["Because I love music, I play guitar.", "I love music; I play guitar every day.", "I love music I play guitar every day.", "I love music, and I play guitar every day."]'::jsonb,2,'Two independent clauses are joined without punctuation.','original'),
('110.22.b.10.D.i',3,'Which sentence has correct subject-verb agreement?','["The books on the shelf is dusty.", "The books on the shelf be dusty.", "The books on the shelf was dusty.", "The books on the shelf are dusty."]'::jsonb,3,'The subject ''books'' is plural.','original'),
('110.22.b.10.D.i',4,'Which is a fragment?','["When the bell rang.", "We waited.", "The bell rang.", "She left."]'::jsonb,0,'A dependent clause cannot stand alone.','original'),
('110.22.b.10.D.ii',3,'Which sentence uses a consistent verb tense?','["She opened the box and finds a note.", "She opened the box and found a note.", "She opens the box and found a note.", "She will open the box and found a note."]'::jsonb,1,'Both verbs are in the past tense.','original'),
('110.22.b.10.D.ii',3,'Choose the correct verb: ''Yesterday, we ____ to the museum.''','["go", "going", "went", "will go"]'::jsonb,2,'Yesterday signals the past.','original'),
('110.22.b.10.D.ii',4,'Which sentence shifts tense incorrectly?','["He walked to school and waved to his friend.", "He will walk to school and wave to his friend.", "He walks to school and waves to his friend.", "He walks to school and waved to his friend."]'::jsonb,3,'Walks (present) and waved (past) clash.','original'),
('110.22.b.10.D.iii',3,'Which conjunctive adverb best completes: ''It was raining; ____, we stayed inside.''?','["therefore", "although", "because", "however"]'::jsonb,0,'It shows a result.','original'),
('110.22.b.10.D.iii',4,'Choose the correct punctuation: ''I wanted to go ____ however, I was too tired.''','[". (no pause)", "; (semicolon)", "- (hyphen)", ", (comma)"]'::jsonb,1,'A semicolon precedes a conjunctive adverb joining two independent clauses.','original'),
('110.22.b.10.D.iv',3,'Which word is the subject in ''The box of pencils is on the desk''?','["pencils", "is", "box", "desk"]'::jsonb,2,'The prepositional phrase does not contain the subject.','original'),
('110.22.b.10.D.iv',4,'Choose the correct verb: ''The group of students ____ waiting.''','["are", "be", "were", "is"]'::jsonb,3,'The subject ''group'' is singular.','original'),
('110.22.b.10.D.iv',3,'Which sentence contains a prepositional phrase?','["The cat slept under the porch.", "The cat slept soundly.", "The cat is tired.", "The cat purred loudly."]'::jsonb,0,'''Under the porch'' is a preposition plus its object.','original'),
('110.22.b.10.D.v',3,'Which pronoun correctly completes ''The girl ____ won the race is my cousin''?','["which", "who", "whose", "whom"]'::jsonb,1,'Who is the subject of ''won''.','original'),
('110.22.b.10.D.v',3,'Which pronoun is a relative pronoun?','["we", "she", "that", "they"]'::jsonb,2,'Relative pronouns introduce clauses.','original'),
('110.22.b.10.D.v',4,'Which sentence uses a relative pronoun correctly?','["The book who I borrowed is overdue.", "The book whose I borrowed is overdue.", "The book whom I borrowed it is overdue.", "The book that I borrowed is overdue."]'::jsonb,3,'That refers to a thing and begins the clause ''that I borrowed''.','original'),
('110.22.b.10.D.vi',3,'Which pair is a correlative conjunction?','["either...or", "because...so", "if...then-ever", "and...but"]'::jsonb,0,'Either/or are paired.','original'),
('110.22.b.10.D.vi',3,'Which subordinating conjunction best completes: ''____ the storm ended, we went outside''?','["Neither", "After", "Or", "Both"]'::jsonb,1,'After introduces a time clause.','original'),
('110.22.b.10.D.vi',4,'Which sentence is complex?','["We worked and she slept.", "We worked.", "Although it was late, we kept working.", "We worked, but she slept."]'::jsonb,2,'It has a dependent and an independent clause.','original'),
('110.22.b.10.D.vii',2,'Which of these words should always be capitalized?','["state", "mountain", "street", "Texas"]'::jsonb,3,'Names of specific places are proper nouns.','original'),
('110.22.b.10.D.vii',3,'Which of these is an acronym that should be written in all capital letters?','["NASA", "pencil", "teacher", "library"]'::jsonb,0,'Acronyms are formed from initials and written in capitals.','original'),
('110.22.b.10.D.vii',3,'Which phrase needs capital letters?','["a club at school", "the Boy Scouts of America", "my class", "a group of friends"]'::jsonb,1,'Names of specific organizations are capitalized.','original'),
('110.22.b.10.D.viii',3,'Which sentence uses a comma correctly after an introductory element?','["After the rain stopped we went, outside.", "After the rain, stopped we went outside.", "After the rain stopped, we went outside.", "After, the rain stopped we went outside."]'::jsonb,2,'Use a comma after an introductory clause.','original'),
('110.22.b.10.D.viii',3,'Which sentence is punctuated correctly?','["However the answer was, wrong.", "However the answer, was wrong.", "However the, answer was wrong.", "However, the answer was wrong."]'::jsonb,3,'A comma follows a transition word.','original'),
('110.22.b.10.D.viii',4,'Which sentence needs a comma?','["Although she was tired she finished the race.", "He ran fast.", "She was tired.", "She finished the race."]'::jsonb,0,'A comma follows an introductory dependent clause.','original'),
('110.22.b.10.D.ix',2,'Which word correctly completes ''The dog wagged ____ tail''?','["it''s", "its", "its''", "it is"]'::jsonb,1,'''Its'' shows possession.','original'),
('110.22.b.10.D.ix',3,'Choose the correct word: ''Lack of sleep can ____ your mood.''','["effect", "affects", "affect", "effects"]'::jsonb,2,'Affect is the verb meaning to influence.','original'),
('110.22.b.10.D.ix',3,'Which sentence uses the right word?','["They''re going to there house over they''re.", "There going to there house over their.", "Their going to they''re house over there.", "They''re going to their house over there."]'::jsonb,3,'They''re = they are; their = possessive; there = place.','original'),
('110.22.b.12.E',3,'Which is a primary source?','["a diary written by a soldier during the war", "an encyclopedia article", "a documentary made in 2020", "a textbook chapter about the war"]'::jsonb,0,'Primary sources are firsthand.','original'),
('110.22.b.12.E',3,'Which is a secondary source?','["a letter written by the president", "a biography of a president written by a historian", "a photograph taken at the event", "an original speech"]'::jsonb,1,'Secondary sources interpret primary ones.','original'),
('110.22.b.12.E',4,'A student needs firsthand accounts of the 1969 moon landing. Which source is best?','["a movie review", "a website listing trivia", "an astronaut''s logbook", "a modern magazine summary"]'::jsonb,2,'A logbook is an original record.','original'),
('110.22.b.12.G',3,'Copying a sentence from a website into your report without credit is...','["summarizing", "paraphrasing", "synthesizing", "plagiarism"]'::jsonb,3,'Using someone''s words as your own is plagiarism.','original'),
('110.22.b.12.G',3,'Which is a proper paraphrase of ''The Amazon holds half of the world''s rainforest'' ?','["About half of Earth''s rainforest is in the Amazon, according to the source.", "Rainforests are nice.", "The Amazon holds half of the world''s rainforest.", "I invented this fact."]'::jsonb,0,'Rephrase and credit the source.','original'),
('110.22.b.12.G',4,'Even when you paraphrase, you should...','["hide the source", "cite the original source", "keep it secret", "copy it word for word"]'::jsonb,1,'Ideas still belong to the source.','original'),
('110.22.b.12.H.i',3,'Which source is most credible for information about vaccines?','["a social media post", "a product ad", "a government health agency website", "an anonymous blog"]'::jsonb,2,'Reliable, expert sources are best.','original'),
('110.22.b.12.H.i',4,'A website selling energy drinks says its drink makes you smarter. What should a careful reader consider?','["the website is always right", "ads are unbiased", "bias doesn''t matter", "the site may be biased toward selling the product"]'::jsonb,3,'Sellers have an interest in the claim.','original'),
('110.22.b.12.H.i',3,'An author shows bias when he...','["presents only one side with loaded words", "gives balanced evidence", "cites several experts", "offers many viewpoints fairly"]'::jsonb,0,'Bias favors one view.','original'),
('110.22.b.12.H.ii',3,'''This is the worst idea in the history of the world!'' is an example of...','["a statistic", "hyperbole", "a definition", "a primary source"]'::jsonb,1,'Extreme exaggeration is hyperbole.','original'),
('110.22.b.12.H.ii',4,'An ad shows a sad puppy to make viewers donate without giving facts about the charity. This is a(n)...','["logical proof", "statistic", "emotional appeal", "primary source"]'::jsonb,2,'It uses feelings, not evidence.','original'),
('110.22.b.12.H.ii',4,'''All teenagers are lazy'' is an example of...','["a statistic", "a definition", "a fact", "a stereotype"]'::jsonb,3,'It overgeneralizes about a group.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
